"use client";

import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
  FieldLegend,
  FieldSet,
} from "@/components/ui/field";
import { fieldMessage, fieldMessageId } from "@/components/ui/form-fields-model";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";

/** 所有字段包装共有的展示 props。包装不持有状态：值、错误都由表单正文传入。 */
type FieldProps = {
  /** 控件的 id；消息行的 id 由它得出（`${id}-message`），出错前后不变。 */
  id: string;
  label: string;
  /** 提示，与错误共用消息行；出错时被错误替换。 */
  hint?: string;
  /** 要显示的错误。显示时机由调用方用 `visibleErrors` 决定。 */
  error?: string | null;
  required?: boolean;
  disabled?: boolean;
};

/** 选项。`value` 不用 `""`、`"none"` 这类哨兵；「没有值」只用 `null`。 */
type FieldOption<T extends string> = { value: T; label: string };

function LabelText({ label, required }: { label: string; required?: boolean }) {
  return (
    <>
      {label}
      {required ? (
        <span aria-hidden="true" className="text-muted-foreground">
          *
        </span>
      ) : null}
    </>
  );
}

/** 提示与错误共用的消息行：固定 id，出错时换成 `text-destructive-subtle-foreground`。 */
function FieldMessage({ id, hint, error }: { id: string; hint?: string; error?: string | null }) {
  const message = fieldMessage(hint, error);
  return (
    <FieldDescription
      id={fieldMessageId(id)}
      className={message.invalid ? "text-destructive-subtle-foreground" : undefined}
    >
      {message.text}
    </FieldDescription>
  );
}

/** 控件上的可访问性属性：`aria-invalid` 只在出错时出现，`aria-describedby` 始终指向消息行。 */
function controlAria({ id, error, required }: Pick<FieldProps, "id" | "error" | "required">) {
  return {
    "aria-invalid": error ? true : undefined,
    "aria-describedby": fieldMessageId(id),
    "aria-required": required ? true : undefined,
  } as const;
}

/** 单行文本字段。`type`、`autoComplete` 原样传给 Input。 */
function TextField({
  id,
  label,
  hint,
  error,
  required,
  disabled,
  value,
  onValueChange,
  type = "text",
  autoComplete,
  placeholder,
}: FieldProps & {
  value: string;
  onValueChange: (value: string) => void;
  type?: "text" | "email" | "password" | "url" | "tel" | "number";
  autoComplete?: string;
  placeholder?: string;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>
        <LabelText label={label} required={required} />
      </FieldLabel>
      <Input
        id={id}
        type={type}
        value={value}
        onChange={(event) => onValueChange(event.target.value)}
        disabled={disabled}
        autoComplete={autoComplete}
        placeholder={placeholder}
        {...controlAria({ id, error, required })}
      />
      <FieldMessage id={id} hint={hint} error={error} />
    </Field>
  );
}

/** 多行文本字段。 */
function TextareaField({
  id,
  label,
  hint,
  error,
  required,
  disabled,
  value,
  onValueChange,
  placeholder,
  rows,
}: FieldProps & {
  value: string;
  onValueChange: (value: string) => void;
  placeholder?: string;
  rows?: number;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>
        <LabelText label={label} required={required} />
      </FieldLabel>
      <Textarea
        id={id}
        value={value}
        onChange={(event) => onValueChange(event.target.value)}
        disabled={disabled}
        placeholder={placeholder}
        rows={rows}
        {...controlAria({ id, error, required })}
      />
      <FieldMessage id={id} hint={hint} error={error} />
    </Field>
  );
}

/**
 * 下拉选一个值。`value` 为 `null` 时显示 `placeholder`；占位项不渲染成 `SelectItem`，
 * 选中后不能清空（select.md「模式：表单字段」）。`onValueChange` 只收到非 `null` 的值。
 */
function SelectField<T extends string>({
  id,
  label,
  hint,
  error,
  required,
  disabled,
  options,
  value,
  onValueChange,
  placeholder = "请选择",
}: FieldProps & {
  options: readonly FieldOption<T>[];
  value: T | null;
  onValueChange: (value: T) => void;
  placeholder?: string;
}) {
  const items = [{ value: null, label: placeholder }, ...options];
  return (
    <Field>
      <FieldLabel htmlFor={id}>
        <LabelText label={label} required={required} />
      </FieldLabel>
      <Select
        items={items}
        value={value}
        onValueChange={(next) => {
          if (next !== null) onValueChange(next);
        }}
        disabled={disabled}
      >
        <SelectTrigger id={id} className="w-full" {...controlAria({ id, error, required })}>
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <FieldMessage id={id} hint={hint} error={error} />
    </Field>
  );
}

/** 两到五个互斥项、要一眼看全时用的单选组。标题是 `FieldLegend`，每项一个 `Field`。 */
function RadioGroupField<T extends string>({
  id,
  label,
  hint,
  error,
  required,
  disabled,
  options,
  value,
  onValueChange,
}: FieldProps & {
  options: readonly FieldOption<T>[];
  value: T | null;
  onValueChange: (value: T) => void;
}) {
  // aria-invalid 加在每个选项上（选项才是控件，提交失败时聚焦第一个出错控件也靠它）。
  const invalid = error ? true : undefined;
  return (
    <FieldSet>
      <FieldLegend variant="label">
        <LabelText label={label} required={required} />
      </FieldLegend>
      <RadioGroup
        value={value}
        onValueChange={(next) => {
          const option = options.find((item) => item.value === next);
          if (option !== undefined) onValueChange(option.value);
        }}
        disabled={disabled}
        aria-describedby={fieldMessageId(id)}
        aria-required={required ? true : undefined}
      >
        {options.map((option) => (
          <Field key={option.value} orientation="horizontal">
            <RadioGroupItem
              id={`${id}-${option.value}`}
              value={option.value}
              aria-invalid={invalid}
            />
            <FieldLabel htmlFor={`${id}-${option.value}`} className="font-normal">
              {option.label}
            </FieldLabel>
          </Field>
        ))}
      </RadioGroup>
      <FieldMessage id={id} hint={hint} error={error} />
    </FieldSet>
  );
}

/** 开关一个布尔值。标签和提示在左，开关在右。 */
function SwitchField({
  id,
  label,
  hint,
  error,
  disabled,
  checked,
  onCheckedChange,
}: Omit<FieldProps, "required"> & {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  return (
    <Field orientation="horizontal">
      <FieldContent>
        <FieldLabel htmlFor={id}>{label}</FieldLabel>
        <FieldMessage id={id} hint={hint} error={error} />
      </FieldContent>
      <Switch
        id={id}
        checked={checked}
        onCheckedChange={(next) => onCheckedChange(next)}
        disabled={disabled}
        {...controlAria({ id, error })}
      />
    </Field>
  );
}

export type {
  FieldErrors,
  TouchedFields,
  Validator,
  Validators,
} from "@/components/ui/form-fields-model";
export {
  blockedReason,
  fieldMessageId,
  hasErrors,
  isDirty,
  required,
  touchChanged,
  validate,
  visibleErrors,
} from "@/components/ui/form-fields-model";
export type { FieldOption };
export { RadioGroupField, SelectField, SwitchField, TextareaField, TextField };

/**
 * 表单的字段模型（ADR 0014）：纯函数与类型，不依赖 React。
 * 状态是一个 `useState<TValues>` 单对象；校验器按字段汇总成 `FieldErrors<TValues>`；
 * 脏态用 `isDirty(values, baseline)` 比较；错误在提交过或碰过字段之后才显示。
 */

/** 校验器：返回中文消息，或 `null` 表示通过。第二个参数是整个 values，用于跨字段校验。 */
export type Validator<TValue, TValues> = (value: TValue, values: TValues) => string | null;

/** 每个字段至多一个校验器。没有校验器的字段不校验。 */
export type Validators<TValues> = { [K in keyof TValues]?: Validator<TValues[K], TValues> };

/** 按字段的错误消息。没有错误的字段不出现。 */
export type FieldErrors<TValues> = Partial<Record<keyof TValues, string>>;

/** 用户改过值的字段。「碰过」即改过。 */
export type TouchedFields<TValues> = Partial<Record<keyof TValues, true>>;

/** 用不换行空格占住消息行：提示和错误都没有时，出错前后布局不跳动。 */
const EMPTY_MESSAGE = " ";

function keysOf<T extends object>(value: T): (keyof T)[] {
  return Object.keys(value) as (keyof T)[];
}

/** 按字段调用校验器，收集非 `null` 的消息。 */
export function validate<TValues extends object>(
  values: TValues,
  validators: Validators<TValues>,
): FieldErrors<TValues> {
  const errors: FieldErrors<TValues> = {};
  for (const key of keysOf(validators)) {
    const message = validators[key]?.(values[key], values) ?? null;
    if (message !== null) errors[key] = message;
  }
  return errors;
}

/** 必填校验：空串（含只有空白）、`null`、`undefined` 判为缺值。 */
export function required(message: string): Validator<unknown, unknown> {
  return (value) => {
    if (value === null || value === undefined) return message;
    if (typeof value === "string" && value.trim() === "") return message;
    return null;
  };
}

/** 有任一条错误消息时为 `true`。 */
export function hasErrors<TValues>(errors: FieldErrors<TValues>): boolean {
  return Object.values(errors).some((message) => message !== undefined);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" && value !== null && Object.getPrototypeOf(value) === Object.prototype
  );
}

/** 按内容比较：原始值用 `Object.is`，数组与普通对象逐项比较。 */
function isEqualValue(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, index) => isEqualValue(item, b[index]));
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const keys = Object.keys(a);
    return (
      keys.length === Object.keys(b).length && keys.every((key) => isEqualValue(a[key], b[key]))
    );
  }
  return false;
}

/** 与基线逐字段按内容比较，任一字段不同即为脏。 */
export function isDirty<TValues extends object>(values: TValues, baseline: TValues): boolean {
  return !isEqualValue(values, baseline);
}

/**
 * 把 `prev` → `next` 之间值有变化的字段记为碰过。
 * 没有新字段被碰时返回 `touched` 本身，`setState` 可以跳过重渲染。
 */
export function touchChanged<TValues extends object>(
  touched: TouchedFields<TValues>,
  prev: TValues,
  next: TValues,
): TouchedFields<TValues> {
  let result = touched;
  for (const key of keysOf(next)) {
    if (result[key] || isEqualValue(prev[key], next[key])) continue;
    if (result === touched) result = { ...touched };
    result[key] = true;
  }
  return result;
}

/** 要显示的错误：提交过之后全部显示，之前只显示碰过的字段。 */
export function visibleErrors<TValues>(
  errors: FieldErrors<TValues>,
  touched: TouchedFields<TValues>,
  submitted: boolean,
): FieldErrors<TValues> {
  if (submitted) return errors;
  const visible: FieldErrors<TValues> = {};
  for (const key of Object.keys(errors) as (keyof TValues)[]) {
    if (touched[key]) visible[key] = errors[key];
  }
  return visible;
}

/**
 * 「为什么不能提交」：按 `labels` 的字段顺序列出有错误的字段。没有错误时为 `null`。
 * 提交按钮用 `aria-describedby` 指向显示它的元素。
 */
export function blockedReason<TValues>(
  errors: FieldErrors<TValues>,
  labels: Record<keyof TValues, string>,
): string | null {
  const names = (Object.keys(labels) as (keyof TValues)[])
    .filter((key) => errors[key] !== undefined)
    .map((key) => labels[key]);
  return names.length === 0 ? null : `还不能提交，请先处理：${names.join("、")}。`;
}

/** 字段消息行的固定 id。提示与错误共用它，控件的 `aria-describedby` 出错前后不变。 */
export function fieldMessageId(id: string): string {
  return `${id}-message`;
}

/** 消息行显示什么：有错误显示错误，否则显示提示；都没有时用不换行空格占住一行。 */
export function fieldMessage(
  hint: string | undefined,
  error: string | null | undefined,
): { text: string; invalid: boolean } {
  if (error) return { text: error, invalid: true };
  return { text: hint || EMPTY_MESSAGE, invalid: false };
}
